<style>
    /* Form background */
    .import-form {
        background-color: #cce5ff; /* xanh dương nhạt */
        padding: 30px;
        border-radius: 12px;
        max-width: 600px;
        margin: 30px auto;
        box-shadow: 0 6px 15px rgba(0,0,0,0.15);
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    }

        /* Khoảng cách đều giữa các dòng */
        .import-form .form-section {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

    .form-group {
        display: flex;
        flex-direction: column;
        gap: 8px; /* khoảng cách giữa label và input/select/file */
    }

    .import-form .form-label {
        font-weight: 600;
        color: #004085;
    }

    .import-form select,
    .import-form input[type=""file""] {
        padding: 8px;
        border-radius: 8px;
        border: 1px solid #004085;
        width: 100%;
        box-sizing: border-box;
        font-size: 14px;
 ");
            WriteLiteral(@"   }

    .form-actions {
        display: flex;
        gap: 15px; /* khoảng cách giữa các button */
        margin-top: 15px;
    }

    .import-form button.btn-secondary {
        background-color: #004085;
        color: white;
        border: none;
        padding: 10px 20px;
        border-radius: 8px;
        cursor: pointer;
        transition: transform 0.2s, box-shadow 0.2s;
    }

        .import-form button.btn-secondary:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.2);
        }

    .normal-text-link button {
        background-color: #6c757d;
    }

    .text-secondary {
        font-size: 13px;
        color: #004085 !important;
    }

    .fade-alert {
        transition: opacity 0.5s ease-in-out;
        opacity: 1;
        margin-bottom: 10px;
    }
</style>

");
